<script setup lang="ts">
import {ref,onMounted,nextTick,watch} from 'vue';import {onShow} from '@dcloudio/uni-app'
import AppPage from '../AppPage.vue';import AppNavbar from '@/components/AppNavbar.vue';import AppButton from '@/components/AppButton.vue';import BaseCard from '@/components/BaseCard.vue';import SectionHeader from '@/components/SectionHeader.vue';import StatusTag from '@/components/StatusTag.vue';import Stage1Field from './Stage1Field.vue';import Stage1Region from './Stage1Region.vue';import Stage1Status from './Stage1Status.vue';import {useStage1Page} from '../../services/use-stage1-page';import {stage1Service,methodLabels,cents,amount,label} from '../../services/stage1';import type {Data,Page} from '../../services/stage1'
const p=useStage1Page('fulfillment'),{error,busy,loading,pending,dirty}=p,configuration=ref<Data|null>(null),methods=ref<Data>({}),points=ref<Page<Data>>({records:[],total:0}),page=ref(1),type=ref(''),reason=ref(''),selection=ref<Data|null>(null),region=ref<Data>({}),pointAction=ref<Data|null>(null);let replacing=false
watch(methods,()=>{if(!replacing)dirty.value=true},{deep:true})
function load(){return p.read(async()=>({config:await stage1Service.read<Data>('/fulfillment'),points:await stage1Service.read<Page<Data>>('/points',{pageNumber:page.value,pageSize:20,...(type.value?{type:type.value}:{})})}),v=>{replacing=true;configuration.value=v.config;methods.value=Object.fromEntries(Object.keys(methodLabels).map(key=>{const item=v.config.methods[key]||{enabled:false,feeCent:null,nationwide:false,districtCodes:[],excludedDistrictCodes:[],description:''};return [key,{...item,feeInput:item.feeCent==null?'':amount(item.feeCent)}]}));points.value=v.points;dirty.value=false;void nextTick(()=>{replacing=false})})}
function pick(method:string,excluded:boolean){selection.value={method,key:excluded?'excludedDistrictCodes':'districtCodes'};region.value={}}
function addDistrict(){if(!selection.value||!region.value.districtCode)return;const values=methods.value[selection.value.method][selection.value.key] as string[];if(!values.includes(region.value.districtCode))values.push(region.value.districtCode);region.value={};selection.value=null}
function nationwide(key:string,value:boolean){methods.value[key].nationwide=value;methods.value[key].districtCodes=[];methods.value[key].excludedDistrictCodes=[]}
async function save(){await p.write(()=>{const value:Data={};for(const key of Object.keys(methodLabels)){const item=methods.value[key],delivery=['MERCHANT_DELIVERY','EXPRESS'].includes(key);value[key]={enabled:item.enabled,feeCent:delivery?cents(item.feeInput):0,nationwide:key==='EXPRESS'&&item.nationwide,districtCodes:delivery&&!item.nationwide?item.districtCodes:[],excludedDistrictCodes:key==='EXPRESS'&&item.nationwide?item.excludedDistrictCodes:[],description:item.description||''}}return p.command('/fulfillment',{expectedVersion:configuration.value!.version,methods:value,reason:reason.value},'PUT')},()=>{reason.value='';return load()})}
function edit(id?:string){uni.navigateTo({url:'/pages/fulfillment/point-editor/index'+(id?'?id='+id:'')})}
async function toggle(){const value=pointAction.value!;await p.write(()=>p.command('/points/'+value.point.id+'/'+(value.point.enabled?'disable':'enable'),{expectedVersion:value.point.version,reason:value.reason}),()=>{pointAction.value=null;return load()})}
onMounted(load);onShow(()=>{if(configuration.value&&!dirty.value&&!pending.value&&!pointAction.value)return load()})
</script>
<template><AppPage secondary :status="loading&&!configuration?'loading':'ready'"><template #navbar><AppNavbar title="履约设置与点位" centered show-back/></template><view class="s1-fulfillment stack"><Stage1Status :error="error" :pending="pending" :busy="busy" @recover="p.recover(load)" @retry="p.retry(load)" @abandon="p.abandon(load)"/><BaseCard v-if="configuration" class="s1-form"><SectionHeader title="店铺履约方式"/><text class="s1-copy">固定费用以同一店铺的一次履约为单位；社区自提、到店核销不收费。实际可用范围还取决于商品与有效点位。</text><view v-for="(title,key) in methodLabels" :key="key" class="s1-method"><SectionHeader :title="title"/><Stage1Field v-model="methods[key].enabled" label="启用方式" type="boolean" :disabled="busy||pending||!p.has('fulfillment.configure')"/><template v-if="key==='MERCHANT_DELIVERY'||key==='EXPRESS'"><Stage1Field v-model="methods[key].feeInput" label="固定费用（元）" type="money" :disabled="busy||pending||!p.has('fulfillment.configure')" hint="启用时必填；明确填0表示免费"/><Stage1Field v-if="key==='EXPRESS'" :model-value="methods[key].nationwide" label="全国可达（可排除区县）" type="boolean" :disabled="busy||pending||!p.has('fulfillment.configure')" @update:model-value="nationwide(String(key),$event)"/><text>{{methods[key].nationwide?'排除区县':'配送区县'}}</text><view v-for="code in methods[key][methods[key].nationwide?'excludedDistrictCodes':'districtCodes']" :key="code" class="s1-district"><text>{{code}}</text><AppButton v-if="p.has('fulfillment.configure')" variant="quiet" :disabled="busy||pending" @click="methods[key][methods[key].nationwide?'excludedDistrictCodes':'districtCodes']=methods[key][methods[key].nationwide?'excludedDistrictCodes':'districtCodes'].filter((v:string)=>v!==code)">移除</AppButton></view><AppButton v-if="p.has('fulfillment.configure')" variant="secondary" :disabled="busy||pending" @click="pick(String(key),methods[key].nationwide)">选择区县</AppButton></template><Stage1Field v-model="methods[key].description" label="方式说明" :maximum="500" :disabled="busy||pending||!p.has('fulfillment.configure')"/><StatusTag :tone="configuration.effectiveMethods.includes(key)?'success':'disabled'">{{configuration.effectiveMethods.includes(key)?'当前有效':'当前无效'}}</StatusTag></view><template v-if="p.has('fulfillment.configure')"><Stage1Field v-model="reason" label="变更原因" required :disabled="busy||pending"/><AppButton :disabled="pending" :loading="busy" @click="save">保存履约配置</AppButton></template></BaseCard><BaseCard v-if="selection" class="s1-form"><SectionHeader title="选择区县"/><Stage1Region v-model="region"/><AppButton :disabled="!region.districtCode" @click="addDistrict">添加所选区县</AppButton><AppButton variant="quiet" @click="selection=null">取消</AppButton></BaseCard><SectionHeader title="店铺点位"/><Stage1Field v-model="type" label="点位类型" type="select" :options="[{value:'',label:'全部'},{value:'COMMUNITY_PICKUP',label:'社区自提'},{value:'STORE_REDEMPTION',label:'到店核销'}]" @update:model-value="page=1;load()"/><AppButton v-if="p.has('point.write')" @click="edit()">新增点位</AppButton><BaseCard v-for="point in points.records" :key="point.id" class="s1-form"><SectionHeader :title="point.name"/><StatusTag :tone="point.enabled?'success':'disabled'">{{point.enabled?'启用':'停用'}} · {{label(point.type)}}</StatusTag><text>{{point.address}}</text><text>{{point.contactName}} · {{point.phone}}</text><text class="s1-copy">影响 {{point.affectedGoods}} 个商品的此类型履约；停用最后一个点位后，只剔除此方式。</text><AppButton variant="secondary" @click="edit(point.id)">查看或编辑点位</AppButton><AppButton v-if="p.has('point.write')" variant="quiet" :disabled="dirty||pending||busy" @click="pointAction={point,reason:''}">{{point.enabled?'停用':'启用'}}点位</AppButton></BaseCard><text v-if="!points.records.length">暂无对应点位。</text><AppButton v-if="page>1" variant="quiet" @click="page--;load()">上一页点位</AppButton><AppButton v-if="page*20<points.total" variant="quiet" @click="page++;load()">下一页点位</AppButton><BaseCard v-if="pointAction" class="s1-form"><SectionHeader :title="pointAction.point.enabled?'停用点位':'启用点位'"/><Stage1Field v-model="pointAction.reason" label="操作原因" :disabled="busy||pending" required/><AppButton :disabled="pending" :loading="busy" @click="toggle">确认</AppButton><AppButton variant="quiet" @click="pointAction=null">取消</AppButton></BaseCard><BaseCard v-if="configuration?.history.length" class="s1-form"><SectionHeader title="配置历史"/><view v-for="item in configuration.history" :key="item.version"><text>第 {{item.version}} 版 · {{item.at}}</text><text class="s1-copy">{{item.reason}}</text></view></BaseCard><AppButton variant="quiet" :loading="loading" @click="load">重新读取</AppButton></view></AppPage></template>
<style scoped lang="scss">.s1-fulfillment{padding:$space-4 $page-gutter}.s1-form,.s1-method{display:flex;flex-direction:column;gap:$space-4;font-size:15px;line-height:1.7;overflow-wrap:anywhere}.s1-copy{display:block;font-size:13px;color:$color-text-secondary}.s1-method{padding:$space-3;background:$color-group-bg;border-radius:$radius-md}.s1-district{display:flex;align-items:center;justify-content:space-between;gap:$space-2}</style>
